mapper.select:
WHERE a.status = 'ACTIVE'
AND a.title LIKE CONCAT('%', #{keyword}, '%')
AND a.activity_start_date <= #{date} AND a.activity_end_date >= #{date}
AND a.daily_capacity >= #{headcount}
ORDER BY a.activity_start_date ASC ORDER BY a.price ASC ORDER BY a.price DESC ORDER BY a.created_at DESC
